// ============================================================================
// Root_of_Trust_apb: APB4 register wrapper around Root_of_Trust_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Root_of_Trust.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Root_of_Trust.md
// ============================================================================
module Root_of_Trust_apb #(
  parameter int IMG_AW = 14
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic otp_req,
  output logic otp_we,
  output logic [5:0] otp_addr,
  output logic [31:0] otp_wdata,
  input logic otp_ack,
  input logic [31:0] otp_rdata,
  output logic [2:0] lc_state,
  output logic cpu_en,
  output logic dbg_en,
  output logic key_valid,
  output logic [255:0] key_out,
  output logic alert,
  output logic [2:0] alert_code,
  input logic esc
);
  localparam logic [31:0] ID_VALUE = 32'h52540100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [15:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd16) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cmd_start;
  logic [1:0]    c_cmd_op;
  logic [5:0]    c_cmd_addr;
  logic [31:0]   c_cmd_data;
  logic [127:0]  c_token;
  logic          c_cmd_busy;
  logic          c_cmd_done;
  logic          c_cmd_err;
  logic [31:0]   c_cmd_rdata;
  logic          c_img_valid;
  logic [31:0]   c_img_data;
  logic          c_img_last;
  logic          c_img_ready;
  logic          c_init_done;
  logic [2:0]    c_lc_state;
  logic          c_boot_done;
  logic          c_boot_ok;
  logic          c_cpu_en;
  logic          c_dbg_en;
  logic          c_key_valid;
  logic          c_alert;
  logic [2:0]    c_alert_code;
  Root_of_Trust_top #(.IMG_AW(IMG_AW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .otp_req(otp_req),
    .otp_we(otp_we),
    .otp_addr(otp_addr),
    .otp_wdata(otp_wdata),
    .otp_ack(otp_ack),
    .otp_rdata(otp_rdata),
    .cmd_start(c_cmd_start),
    .cmd_op(c_cmd_op),
    .cmd_addr(c_cmd_addr),
    .cmd_data(c_cmd_data),
    .token(c_token),
    .cmd_busy(c_cmd_busy),
    .cmd_done(c_cmd_done),
    .cmd_err(c_cmd_err),
    .cmd_rdata(c_cmd_rdata),
    .img_valid(c_img_valid),
    .img_data(c_img_data),
    .img_last(c_img_last),
    .img_ready(c_img_ready),
    .init_done(c_init_done),
    .lc_state(c_lc_state),
    .boot_done(c_boot_done),
    .boot_ok(c_boot_ok),
    .cpu_en(c_cpu_en),
    .dbg_en(c_dbg_en),
    .key_valid(c_key_valid),
    .key_out(key_out),
    .alert(c_alert),
    .alert_code(c_alert_code),
    .esc(esc)
  );
  assign cpu_en = c_cpu_en;  // also readable in the registers
  assign dbg_en = c_dbg_en;  // also readable in the registers
  assign key_valid = c_key_valid;  // also readable in the registers
  assign lc_state = c_lc_state;  // also readable in the registers
  assign alert = c_alert;  // also readable in the registers
  assign alert_code = c_alert_code;  // also readable in the registers

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_CMD_DATA;   // 12'h018 CMD_DATA
  logic [31:0] r_TOKEN0;   // 12'h01C TOKEN0
  logic [31:0] r_TOKEN1;   // 12'h020 TOKEN1
  logic [31:0] r_TOKEN2;   // 12'h024 TOKEN2
  logic [31:0] r_TOKEN3;   // 12'h028 TOKEN3
  logic [0:0] p_CMD;   // 12'h02C CMD (pulses)
  logic [31:0] h_IMG0;   // 12'h030 IMG0 holding register
  logic [0:0] h_IMG1;   // 12'h034 IMG1 holding register
  logic full_IMG;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 8'h0;
      r_CMD_DATA <= 32'h0;
      r_TOKEN0 <= 32'h0;
      r_TOKEN1 <= 32'h0;
      r_TOKEN2 <= 32'h0;
      r_TOKEN3 <= 32'h0;
      p_CMD <= '0;
      h_IMG0 <= '0;
      h_IMG1 <= '0;
      full_IMG <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[6]) r_CMD_DATA <= (r_CMD_DATA & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_TOKEN0 <= (r_TOKEN0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_TOKEN1 <= (r_TOKEN1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_TOKEN2 <= (r_TOKEN2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_TOKEN3 <= (r_TOKEN3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[11]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[12] && !full_IMG) h_IMG0 <= (h_IMG0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13] && !full_IMG) h_IMG1 <= (h_IMG1 & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[13] && !full_IMG) full_IMG <= 1'b1;
      else if (full_IMG && c_img_ready) full_IMG <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cmd_op = r_CTRL[1:0];
  assign c_cmd_addr = r_CTRL[7:2];
  assign c_cmd_data = r_CMD_DATA[31:0];
  assign c_token[31:0] = r_TOKEN0[31:0];
  assign c_token[63:32] = r_TOKEN1[31:0];
  assign c_token[95:64] = r_TOKEN2[31:0];
  assign c_token[127:96] = r_TOKEN3[31:0];
  assign c_cmd_start = p_CMD;
  assign c_img_data[31:0] = h_IMG0[31:0];
  assign c_img_last = h_IMG1;
  assign c_img_valid = full_IMG;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_cmd_done;
    irq_set[1] = c_cmd_err;
    irq_set[2] = c_boot_done;
    irq_set[3] = c_alert;
    irq_set[4] = full_IMG & c_img_ready;
    irq_set[5] = wr & (hit[12] | hit[13]) & full_IMG;
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {full_IMG};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_CMD_DATA);
      10'd7: apb_rdata = 32'(r_TOKEN0);
      10'd8: apb_rdata = 32'(r_TOKEN1);
      10'd9: apb_rdata = 32'(r_TOKEN2);
      10'd10: apb_rdata = 32'(r_TOKEN3);
      10'd12: apb_rdata = 32'(h_IMG0);
      10'd13: apb_rdata = 32'(h_IMG1);
      10'd14: apb_rdata = 32'({c_cmd_rdata});
      10'd15: apb_rdata = 32'({c_alert_code, c_key_valid, c_dbg_en, c_cpu_en, c_boot_ok, c_lc_state, c_init_done, c_cmd_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
